from functools import lru_cache

class Solution:
    def minimumWhiteTiles(self, floor: str, numCarpets: int, carpetLen: int) -> int:
        n = len(floor)

        @lru_cache(maxsize=None)
        def f(i, j):
            if i >= n:
                return 0
            res = f(i + 1, j) + (floor[i] == "1")
            if j:
                res = min(res, f(min(n, i + carpetLen), j - 1))
            return res

        return f(0, numCarpets)

