class Solution {
    private int[][] memo;
    private String floor;
    private int n, carpetLen;

    public int minimumWhiteTiles(String floor, int numCarpets, int carpetLen) {
        this.floor = floor;
        this.carpetLen = carpetLen;
        n = floor.length();
        memo = new int[n][numCarpets + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        return f(0, numCarpets);
    }

    private int f(int i, int j) {
        if (i >= n) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        int res = f(i + 1, j) + (floor.charAt(i) == '1' ? 1 : 0);
        if (j > 0) res = Math.min(res, f(Math.min(n, i + carpetLen), j - 1));
        return memo[i][j] = res;
    }
};

